    parser: logfmt: fix overflow (oss-fuzz)

    Signed-off-by: Eduardo Silva <eduardo@treasure-data.com>

diff --git a/src/flb_parser_logfmt.c b/src/flb_parser_logfmt.c
index 949a5f34e..5ad0f7d0e 100644
--- a/src/flb_parser_logfmt.c
+++ b/src/flb_parser_logfmt.c
@@ -88,7 +88,7 @@ static int logfmt_parser(struct flb_parser *parser,

     while (c < end) {
         /* garbage */
-        while (!ident_byte[*c] && (c < end)) {
+        while ((c < end) && !ident_byte[*c]) {
             c++;
         }
         if (c == end) {
@@ -96,7 +96,7 @@ static int logfmt_parser(struct flb_parser *parser,
         }
         /* key */
         key = c;
-        while (ident_byte[*c] && (c < end)) {
+        while ((c < end) && ident_byte[*c]) {
             c++;
         }
         key_len = c - key;
